-- Esquema H2 criado pelo Exposed no commit 69f8928, anterior ao Flyway.
-- Fixture congelada para testar adoção; não atualizar junto das novas Table ou migrações.
-- Somente estrutura: sem usuários, senhas ou registros exportados.
CREATE CACHED TABLE "PUBLIC"."ACCOUNTS"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "EMAIL" CHARACTER VARYING(255) NOT NULL,
    "ACCESS_TOKEN" CHARACTER VARYING NOT NULL,
    "REFRESH_TOKEN" CHARACTER VARYING NOT NULL,
    "TOKEN_EXPIRY" TIMESTAMP(9) NOT NULL,
    "IS_DEFAULT" BOOLEAN DEFAULT FALSE NOT NULL,
    "LAST_FULL_SYNC" TIMESTAMP(9),
    "CREATED_AT" TIMESTAMP(9) DEFAULT CURRENT_TIMESTAMP NOT NULL
);
ALTER TABLE "PUBLIC"."ACCOUNTS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_A" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."FOLDER_MAPPINGS"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ACCOUNT_ID" INTEGER NOT NULL,
    "DRIVE_FOLDER_ID" CHARACTER VARYING(100) NOT NULL,
    "DRIVE_FOLDER_NAME" CHARACTER VARYING(255) NOT NULL,
    "LOCAL_FOLDER_PATH" CHARACTER VARYING NOT NULL,
    "SYNC_DIRECTION" CHARACTER VARYING(20) DEFAULT 'BIDIRECTIONAL' NOT NULL,
    "LAST_SYNC" TIMESTAMP(9),
    "ENABLED" BOOLEAN DEFAULT TRUE NOT NULL
);
ALTER TABLE "PUBLIC"."FOLDER_MAPPINGS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_C" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."SYNC_HISTORY"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ACCOUNT_ID" INTEGER NOT NULL,
    "MAPPING_ID" INTEGER,
    "DRIVE_FILE_ID" CHARACTER VARYING(100) NOT NULL,
    "FILE_NAME" CHARACTER VARYING(255) NOT NULL,
    "FILE_PATH" CHARACTER VARYING NOT NULL,
    "DIRECTION" CHARACTER VARYING(10) NOT NULL,
    "STATUS" CHARACTER VARYING(10) NOT NULL,
    "FILE_SIZE" BIGINT NOT NULL,
    "timestamp" TIMESTAMP(9) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "ERROR_MESSAGE" CHARACTER VARYING
);
ALTER TABLE "PUBLIC"."SYNC_HISTORY" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_6" PRIMARY KEY("ID");
ALTER TABLE "PUBLIC"."ACCOUNTS" ADD CONSTRAINT "PUBLIC"."ACCOUNTS_EMAIL_UNIQUE" UNIQUE NULLS DISTINCT ("EMAIL");
ALTER TABLE "PUBLIC"."FOLDER_MAPPINGS" ADD CONSTRAINT "PUBLIC"."FK_FOLDER_MAPPINGS_ACCOUNT_ID__ID" FOREIGN KEY("ACCOUNT_ID") REFERENCES "PUBLIC"."ACCOUNTS"("ID") ON UPDATE RESTRICT ON DELETE RESTRICT NOCHECK;
ALTER TABLE "PUBLIC"."SYNC_HISTORY" ADD CONSTRAINT "PUBLIC"."FK_SYNC_HISTORY_MAPPING_ID__ID" FOREIGN KEY("MAPPING_ID") REFERENCES "PUBLIC"."FOLDER_MAPPINGS"("ID") ON UPDATE RESTRICT ON DELETE RESTRICT NOCHECK;
ALTER TABLE "PUBLIC"."SYNC_HISTORY" ADD CONSTRAINT "PUBLIC"."FK_SYNC_HISTORY_ACCOUNT_ID__ID" FOREIGN KEY("ACCOUNT_ID") REFERENCES "PUBLIC"."ACCOUNTS"("ID") ON UPDATE RESTRICT ON DELETE RESTRICT NOCHECK;
